var n=`1387-saoto-soup`;var t=`world-1387`;var o=`SR`;var s=`south-america`;var a=4;var r=110;var g={en:`Saoto Soup`,ua:`Суп саото`};var l={en:`Saoto Soup is a dish from Suriname featuring whole chicken, lemongrass, rice vermicelli, chicken egg. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Суп саото, страва кухні країни Суринам з такими основними складниками: ціла курка, лемонграс, рисова вермішель, куряче яйце. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 70 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 70 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:70,i:[[`whole-chicken`,1100,`g`],[`water`,1600,`ml`],[`lemongrass`,2,`pcs`],[`ground-ginger`,40,`g`]]},{en:`Shred the fully cooked meat into thin pieces with clean forks, discarding bones and tough connective tissue.`,ua:`Розберіть повністю приготоване м’ясо чистими виделками на тонкі волокна, видаливши кістки й жорсткі частини.`,t:[`shredding`,`mixing`],m:8,i:[]},{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`rice-vermicelli`,380,`g`],[`water`,950,`ml`]]},{en:`Boil the eggs until both white and yolk are set; peel and halve only after cooling.`,ua:`Відваріть яйця до повної готовності білків і жовтків; остудіть, очистьте та розріжте навпіл.`,t:[`hard-boiling-eggs`],m:11,i:[[`chicken-egg`,3,`pcs`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`garlic`,4,`clove`],[`canola-oil`,35,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`bean-sprouts`,200,`g`],[`green-onion`,25,`g`],[`light-soy-sauce`,35,`ml`]]}];var d={slug:n,id:t,country:`SR`,region:s,servings:4,minutes:110,title:g,text:l,steps:m};export{o as country,d as default,t as id,r as minutes,s as region,a as servings,n as slug,m as steps,l as text,g as title};